mapper.select:
SELECT q.id AS question_id, q.type AS question_type, q.content AS question_content, sa.error_type, t.id AS source_task_id, t.title AS source_task_name, sa.score AS student_score, tqr.score AS full_score, sa.created_at AS wrong_time FROM student_answers sa INNER JOIN student_submissions ss ON sa.submission_id = ss.id INNER JOIN task_question_rel tqr ON sa.question_id = tqr.question_id INNER JOIN tasks t ON tqr.task_id = t.id INNER JOIN questions q ON sa.question_id = q.id WHERE ss.student_id = #{studentId} AND sa.error_type IS NOT NULL
AND q.course_id = #{courseId}
ORDER BY sa.created_at DESC

SELECT t.id AS task_id, t.course_id, c.name AS course_name, t.title, t.description, t.type, t.total_score, t.start_time, t.deadline, t.status AS task_status, ss.status AS submit_status, ss.total_score AS user_score FROM tasks t INNER JOIN task_student_rel rel ON t.id = rel.task_id LEFT JOIN courses c ON t.course_id = c.id LEFT JOIN student_submissions ss ON t.id = ss.task_id AND rel.student_id = ss.student_id WHERE rel.student_id = #{userId} AND t.status = 'published'
AND t.course_id = #{courseId}
AND ss.status = #{status}
ORDER BY t.created_at DESC LIMIT #{pageable.offset}, #{pageable.pageSize}

SELECT count(*)
FROM tasks t
INNER JOIN task_student_rel rel ON t.id = rel.task_id
LEFT JOIN student_submissions ss ON t.id = ss.task_id AND rel.student_id = ss.student_id
WHERE rel.student_id = #{userId}
AND t.status = 'published'

    AND t.course_id = #{courseId}


    AND ss.status = #{status}

SELECT t.id AS task_id, t.course_id, c.name AS course_name, t.title, t.description, t.type, t.total_score, t.start_time, t.deadline, t.status AS task_status, ss.status AS submit_status, ss.total_score AS user_score FROM tasks t LEFT JOIN courses c ON t.course_id = c.id LEFT JOIN student_submissions ss ON t.id = ss.task_id AND ss.student_id = #{userId} WHERE t.assigner_id = #{userId}
AND t.course_id = #{courseId}
AND ss.status = #{status}
ORDER BY t.created_at DESC LIMIT #{pageable.offset}, #{pageable.pageSize}

SELECT count(*)
FROM tasks t
LEFT JOIN courses c ON t.course_id = c.id
LEFT JOIN student_submissions ss ON t.id = ss.task_id AND ss.student_id = #{userId}
WHERE t.assigner_id = #{userId}

    AND t.course_id = #{courseId}


    AND ss.status = #{status}
